    for (const key of ['fleet', 'logistics', 'airwing']) { const U = UPGRADES[key], lv = c.upgrades[ef][key]; if (lv < U.levels.length - 1 && c.credits[ef] >= U.cost[lv + 1] * k) { c.credits[ef] -= U.cost[lv + 1]; c.upgrades[ef][key]++; } }
