      let lk = 0;
      if (u.def.aa) { const t = S.aimTarget(w, u, S.eyeOf(u, tmpB), tmpA, 0.14, 1200, (e) => e.kind === 'fighter'); lk = t ? lockId(w, u, t) : 0; if (!lk) return; }
      landAlt(w, u, tmpA, lk);
