      for (let i = 0; i < 6; i++) { const a = i / 6 * E.TAU; head.box(0.3, 0.3, 0.6, Math.cos(a) * 2.0, 0, Math.sin(a) * 2.0, c3, { ry: -a, mode: 1 }); }
