      const gl = new T.Sprite(E.Mat.sprite({ map: E.ArtStruct.glowTex(), color: new T.Color(...F.palette.glow.map(v => v / 255 * 3)), additive: true })); gl.scale.setScalar(9); gl.position.y = 6.5; root.add(gl); out.glow = gl;
