      this.domes = new Map(); this.beams = []; this.objs = new Map(); this.t = 0;
      this._m = new T.Matrix4(); this._q = new T.Quaternion(); this._p = new T.Vector3(); this._s = new T.Vector3(); this._c = new T.Color(); this._y = new T.Vector3(0, 1, 0);
