    aaflak: 'pd', aamissile: 'missile', turret: 'pulse', nestgun: 'repeater', ioncannon: 'ion', laser: 'laser', missile: 'missile', chin: 'chin', pod: 'pod', ptorp: 'torpedo', bomb: 'bombaway',
