      const html = f(S.own, 'OURS') + f(S.enemy, 'THEIRS') + (S.escort && S.escort.length ? '<span class="warnt">ESCORT NEEDED</span>' : '') + (S.boarding ? '<span class="warnt">BOARDING</span>' : '');
