    ensure(s) { s.mix = Object.assign({}, SettingsUI.defaults.mix, s.mix || {}, s.volume != null && !(s.mix && s.mix.master != null) ? { master: s.volume } : {}); if (s.uiScale == null) s.uiScale = 1; if (s.palette == null) s.palette = 'default'; return s; },
