  const ARC_NAMES = ['FORE', 'AFT', 'PORT', 'STBD'];
  const arcColor = (f) => f > 0.6 ? '#5ac8ff' : f > 0.25 ? '#ffc24a' : f > 0.02 ? '#ff7a3a' : '#5b6575';

